<template><div class="task-page"><el-card><template #header><div class="task-card-header"><span>调度任务</span><el-button type="primary" @click="open()">新建任务</el-button></div></template><el-table :data="jobs"><el-table-column prop="jobName" label="任务名称"/><el-table-column label="任务类型"><template #default="{row}">{{typeName(row.jobType)}}</template></el-table-column><el-table-column prop="cronExpression" label="Cron"/><el-table-column label="启用"><template #default="{row}"><el-switch :model-value="row.enabled" @change="onToggle(row,$event)"/></template></el-table-column><el-table-column label="操作" width="170"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button><el-button link @click="showLogs(row)">执行日志</el-button></template></el-table-column></el-table></el-card>
<el-card><template #header>最近执行日志</template><el-table :data="logs"><el-table-column prop="jobId" label="任务 ID" width="90"/><el-table-column prop="startedAt" label="开始时间" width="180"/><el-table-column prop="finishedAt" label="结束时间" width="180"/><el-table-column label="结果" width="100"><template #default="{row}"><el-tag :type="row.success?'success':row.success===false?'danger':'info'">{{row.success?'成功':row.success===false?'失败':'运行中'}}</el-tag></template></el-table-column><el-table-column prop="resultMessage" label="执行信息"/></el-table></el-card>
<el-dialog v-model="visible" :title="editing?'编辑任务':'新建任务'" width="600px"><el-form :model="form" label-width="90px"><el-form-item label="任务名称" required><el-input v-model="form.jobName"/></el-form-item><el-form-item label="任务类型"><el-select v-model="form.jobType" style="width:100%"><el-option v-for="o in types" :key="o.value" :label="o.label" :value="o.value"/></el-select></el-form-item><el-form-item label="Cron" required><el-input v-model="form.cronExpression" placeholder="0 0/5 * * * ?"/><div class="form-help">Quartz Cron，例如每 5 分钟：0 0/5 * * * ?</div></el-form-item><el-form-item label="任务配置"><el-input v-model="form.configJson" type="textarea" :rows="4" placeholder="可选 JSON 配置"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">import{ElMessage}from'element-plus';import{onMounted,reactive,ref}from'vue';import{createJob,listJobLogs,listJobs,toggleJob,updateJob,type JobLog,type SchedulerJob}from'@/api/scheduler';const types=[{label:'提醒扫描',value:'REMINDER_SCAN'},{label:'股票采集',value:'STOCK_COLLECT'},{label:'金价采集',value:'GOLD_COLLECT'},{label:'数据备份',value:'DATA_BACKUP'},{label:'学习复习提醒',value:'LEARNING_REVIEW'},{label:'系统健康检查',value:'HEALTH_CHECK'}],jobs=ref<SchedulerJob[]>([]),logs=ref<JobLog[]>([]),visible=ref(false),editing=ref<number>();const blank=()=>({jobName:'',jobType:'REMINDER_SCAN',cronExpression:'0 0/5 * * * ?',enabled:true,configJson:'{}'});const form=reactive(blank());function typeName(v:string){return types.find(x=>x.value===v)?.label||v;}async function load(){jobs.value=(await listJobs()).data;logs.value=(await listJobLogs()).data;}function open(row?:SchedulerJob){editing.value=row?.id;Object.assign(form,blank(),row||{});visible.value=true;}async function save(){if(!form.jobName||!form.cronExpression){ElMessage.warning('请填写任务名称和 Cron');return;}editing.value?await updateJob(editing.value,form):await createJob(form);ElMessage.success('任务已保存并同步到 Quartz');visible.value=false;await load();}function onToggle(row:SchedulerJob,value:string|number|boolean){void toggle(row,Boolean(value));}async function toggle(row:SchedulerJob,enabled:boolean){await toggleJob(row.id,enabled);await load();}async function showLogs(row:SchedulerJob){logs.value=(await listJobLogs(row.id)).data;}onMounted(load);</script>